SELECT CASE WHEN salary >= 152000 THEN 'high' WHEN salary >= 49000 THEN 'mid' ELSE 'low' END AS salary_bucket, AVG(salary) AS avg_salary, SUM(CASE WHEN job_title = 'Intern' THEN salary ELSE 0 END) AS intern_salary FROM employees WHERE MONTH(hire_date) IN (1, 3, 6) GROUP BY CASE WHEN salary >= 152000 THEN 'high' WHEN salary >= 49000 THEN 'mid' ELSE 'low' END ORDER BY avg_salary DESC, 1;
